-- yoru: out ~/.config/nvim/colors/yoru.lua
-- yoru: needs nvim
-- yoru: then for s in "${XDG_RUNTIME_DIR:-/tmp}"/nvim.*.0; do [ -S "$s" ] && nvim --server "$s" --remote-expr 'execute("if get(g:, \"colors_name\", \"\") ==# \"yoru\" | colorscheme yoru | endif")' >/dev/null 2>&1; done; true
-- generated by yoru from the wallpaper: `colorscheme yoru` (open nvims follow a new wallpaper)
vim.cmd.highlight("clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd.syntax("reset") end
vim.o.background = "{{mode}}"
vim.g.colors_name = "yoru"

local c = {
  bg = "#{{surface}}", low = "#{{surface_container_low}}", mid = "#{{surface_container}}",
  high = "#{{surface_container_high}}", top = "#{{surface_container_highest}}",
  fg = "#{{on_surface}}", dim = "#{{on_surface_variant}}", faint = "#{{outline}}", ghost = "#{{outline_variant}}",
  primary = "#{{primary}}", on_primary = "#{{on_primary}}", pc = "#{{primary_container}}", on_pc = "#{{on_primary_container}}",
  secondary = "#{{secondary}}", tertiary = "#{{tertiary}}", error = "#{{error}}",
  red = "#{{color9}}", green = "#{{color10}}", yellow = "#{{color11}}", blue = "#{{color12}}",
  magenta = "#{{color13}}", cyan = "#{{color14}}",
}
local hl = function(group, spec) vim.api.nvim_set_hl(0, group, spec) end

hl("Normal", { fg = c.fg, bg = c.bg })
hl("NormalFloat", { fg = c.fg, bg = c.low })
hl("FloatBorder", { fg = c.ghost, bg = c.low })
hl("FloatTitle", { fg = c.primary, bg = c.low, bold = true })
hl("Cursor", { fg = c.on_primary, bg = c.primary })
hl("CursorLine", { bg = c.low })
hl("CursorColumn", { bg = c.low })
hl("ColorColumn", { bg = c.low })
hl("LineNr", { fg = c.ghost })
hl("CursorLineNr", { fg = c.primary, bold = true })
hl("SignColumn", { bg = c.bg })
hl("VertSplit", { fg = c.ghost })
hl("WinSeparator", { fg = c.ghost })
hl("Visual", { bg = c.pc, fg = c.on_pc })
hl("Search", { bg = "#{{tertiary_container}}", fg = "#{{on_tertiary_container}}" })
hl("IncSearch", { bg = c.primary, fg = c.on_primary })
hl("CurSearch", { bg = c.primary, fg = c.on_primary })
hl("MatchParen", { fg = c.primary, bold = true, underline = true })
hl("Pmenu", { fg = c.fg, bg = c.mid })
hl("PmenuSel", { fg = c.on_pc, bg = c.pc, bold = true })
hl("PmenuSbar", { bg = c.high })
hl("PmenuThumb", { bg = c.faint })
hl("StatusLine", { fg = c.fg, bg = c.mid })
hl("StatusLineNC", { fg = c.faint, bg = c.low })
hl("TabLine", { fg = c.dim, bg = c.low })
hl("TabLineSel", { fg = c.on_primary, bg = c.primary, bold = true })
hl("TabLineFill", { bg = c.bg })
hl("Folded", { fg = c.dim, bg = c.low })
hl("NonText", { fg = c.ghost })
hl("Whitespace", { fg = c.ghost })
hl("Directory", { fg = c.primary })
hl("Title", { fg = c.primary, bold = true })
hl("ErrorMsg", { fg = c.error })
hl("WarningMsg", { fg = c.yellow })
hl("MoreMsg", { fg = c.green })
hl("Question", { fg = c.primary })

hl("Comment", { fg = c.faint, italic = true })
hl("Constant", { fg = c.tertiary })
hl("String", { fg = c.green })
hl("Character", { fg = c.green })
hl("Number", { fg = c.tertiary })
hl("Boolean", { fg = c.tertiary })
hl("Identifier", { fg = c.fg })
hl("Function", { fg = c.primary })
hl("Statement", { fg = c.magenta })
hl("Keyword", { fg = c.magenta })
hl("Operator", { fg = c.dim })
hl("PreProc", { fg = c.cyan })
hl("Type", { fg = c.yellow })
hl("Special", { fg = c.cyan })
hl("Delimiter", { fg = c.dim })
hl("Todo", { fg = c.on_primary, bg = c.primary, bold = true })
hl("Underlined", { underline = true })

hl("DiagnosticError", { fg = c.error })
hl("DiagnosticWarn", { fg = c.yellow })
hl("DiagnosticInfo", { fg = c.blue })
hl("DiagnosticHint", { fg = c.cyan })
hl("DiagnosticUnderlineError", { undercurl = true, sp = c.error })
hl("DiagnosticUnderlineWarn", { undercurl = true, sp = c.yellow })
hl("DiffAdd", { bg = "#{{color2}}", fg = c.bg })
hl("DiffChange", { bg = c.high })
hl("DiffDelete", { fg = c.error })
hl("DiffText", { bg = c.pc, fg = c.on_pc })
hl("GitSignsAdd", { fg = c.green })
hl("GitSignsChange", { fg = c.yellow })
hl("GitSignsDelete", { fg = c.red })

hl("@variable", { fg = c.fg })
hl("@variable.member", { fg = c.secondary })
hl("@property", { fg = c.secondary })
hl("@function.builtin", { fg = c.cyan })
hl("@constructor", { fg = c.yellow })
hl("@keyword.return", { fg = c.magenta, italic = true })
hl("@punctuation.bracket", { fg = c.dim })
hl("@tag", { fg = c.primary })
hl("@tag.attribute", { fg = c.secondary })
